"""Content-addressed URLs for the two shared runtime bundles."""

from __future__ import annotations

from hashlib import sha256
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
RUNTIME_NAMES = ("site.css", "site.js")


def runtime_path(name: str) -> str:
    """Derive the public path from the exact generated bytes, not a release number."""
    if name not in RUNTIME_NAMES:
        raise ValueError(f"Unknown runtime bundle: {name}")
    stem, suffix = name.split(".")
    digest = sha256((ROOT / "assets" / name).read_bytes()).hexdigest()
    return f"assets/{stem}.{digest}.{suffix}"


def runtime_url(name: str) -> str:
    return "/" + runtime_path(name)
